(125037, 'ptBR', '$gSenhor:Senhora; do Éter $p! Eu não esperava que o agente Fagulhaço voltasse com $Go maior campeão:a maior campeã; da Aliança!', '', 25549),
(125036, 'ptBR', 'Clarividente $p! Eu não esperava que o Agente Fagulhaço voltasse com $Go maior campeão:a maior campeã; da Aliança!', '', 25549),
(125035, 'ptBR', 'Umbralâmina $p! Eu não esperava que o Agente Fagulhaço voltasse com $Go maior campeão:a maior campeã; da Aliança!', '', 25549),
(125034, 'ptBR', '$GSumo Sacerdote:Suma Sacerdotisa; $p! Eu não esperava que o Agente Fagulhaço voltasse com $Go maior campeão:a maior campeã; da Aliança!', '', 25549),
