(120115, 'ptBR', 'Efeito sonoro para tropas', '', 25549),
(120114, 'ptBR', '', 'Eu me juntarei aos meus irmãos e irmãs caídos. Adeus, Lyrea.', 25549),
(120113, 'ptBR', 'Efeito sonoro para tropas', '', 25549),
