(116810, 'ptBR', 'Detenha-o! Não faça economia!', 'Detenha-o! Não faça economia!', 25549),
(116809, 'ptBR', 'Tenu''balah.', '', 25549),
(116808, 'ptBR', '', 'Est$ge:a; não é qualquer mortal. $n foi escolhid$go:a; pelo próprio Odyn!', 25549),
(116807, 'ptBR', 'Vamos reconstruir o mundo.', '', 25549),
(116806, 'ptBR', 'O que quer de mim?', '', 25549),
(116805, 'ptBR', 'Saudações.', '', 25549),
(116804, 'ptBR', 'Um mortal lidera os exércitos da Fortaleza Celeste? Blasfêmia!', '', 25549),
(116803, 'ptBR', 'Espere, Hodir! Eu trouxe ajuda. Esses demônios imundos não são páreo para nós!', '', 25549),
(116802, 'ptBR', 'Tu se arrependerás disto!', '', 25549),
(116801, 'ptBR', 'Você não pertence a este lugar, demônio. Saia daqui!', '', 25549),
(116800, 'ptBR', 'Por Ulduar!', '', 25549),
(116799, 'ptBR', 'Você profana o templo com sua presença, demônio!', '', 25549),
(116798, 'ptBR', 'Morra, verme!', '', 25549),
(116793, 'ptBR', 'Não adianta!', 'É inútil resistir...', 25549),
(116792, 'ptBR', 'Os Filhos da Noite governarão este mundo!', 'Os shal''dorei dominarão este mundo!', 25549),
(116791, 'ptBR', 'Arash-falas...', 'Arash-falas...', 25549),
(116790, 'ptBR', 'Tor''theras falar!', 'Tor''theras falar!', 25549),
(116789, 'ptBR', 'Nós... fracassamos.', 'Minha magia... foi derrotada?', 25549),
