INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(116167, 'ptBR', 'Vamos testar seu conhecimento de história, então! Qual é o nome do humano que manteve Thrall como um escravo no Forte do Desterro?', '', 25549),
